sp_theme.css_variables:
$brand-primary: #ff4fa3;
$navbar-inverse-bg: #ff69b4;
$navbar-inverse-link-color: white;
$body-bg: #fff5fa;
$link-color: #d63384;
 
.navbar-inverse .navbar-nav > li > a {
    color: #ffffff !important;
    font-weight: 500;
}
 
.navbar-inverse .navbar-nav > li > a:hover {
    color: #ffe3f1 !important;
}
 
.navbar-inverse .navbar-text {
    color: #ffffff !important;
}
 
.breadcrumb {
    background: transparent;
}
 
.breadcrumb a {
    color: #ff4fa3 !important;
    font-weight: 500;
}
 
.breadcrumb > .active {
    color: #666 !important;
}
 
.breadcrumb > li + li:before {
    color: #ffb3d1 !important;
}
 
.navbar-inverse {
    background: linear-gradient(90deg, #ff4fa3, #ff6fb5);
    border: none;
}
 
.navbar-inverse {
    border-bottom: 3px solid #ff4fa3 !important;
}
